import pytest

from target import ticket_state_after


def test_open_ticket_can_be_assigned():
    assert ticket_state_after("OPEN", "ASSIGN") == "ASSIGNED"


def test_start_requires_assigned_ticket():
    with pytest.raises(ValueError):
        ticket_state_after("OPEN", "START")


def test_closed_ticket_cannot_be_restarted():
    with pytest.raises(ValueError):
        ticket_state_after("CLOSED", "START")
